package br.edu.cesar.treinoconecta.treinoconectacore.infraestrutura.core.desafio;

import java.time.OffsetDateTime;import java.util.*;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.data.domain.*;
import br.edu.cesar.treinoconecta.treinoconectacore.aplicacao.core.aulasdesafios.AulasDesafiosDados;import br.edu.cesar.treinoconecta.treinoconectacore.aplicacao.core.desafio.*;import br.edu.cesar.treinoconecta.treinoconectacore.aplicacao.core.desafio.spi.IDesafioAplicacaoRepositorio;import dev.sauloaraujo.d5.framework.infraestrutura.AgregadoAplicacaoRepositorioAbstrato;

public final class DesafioAplicacaoRepositorio extends AgregadoAplicacaoRepositorioAbstrato<AulasDesafiosDados.DesafioLinha,DesafioOrdenacao,DesafioConsulta> implements IDesafioAplicacaoRepositorio{
 private final JdbcTemplate jdbc;public DesafioAplicacaoRepositorio(JdbcTemplate jdbc){this.jdbc=Objects.requireNonNull(jdbc);}
 protected Page<AulasDesafiosDados.DesafioLinha> pesquisar(DesafioConsulta consulta,Pageable pagina){var linhas=desafios();int inicio=Math.min((int)pagina.getOffset(),linhas.size());int fim=Math.min(inicio+pagina.getPageSize(),linhas.size());return new PageImpl<>(linhas.subList(inicio,fim),pagina,linhas.size());}
 protected String paraPropriedadeOrdenacao(DesafioOrdenacao ordenacao){return "inicio";}
 public List<AulasDesafiosDados.PessoaLinha> alunos(){return jdbc.query("select ALU_ID,ALU_NOME from ALU_ALUNO where ALU_ATIVO=true order by ALU_NOME",(r,n)->new AulasDesafiosDados.PessoaLinha(r.getLong(1),r.getString(2)));}
 public List<AulasDesafiosDados.DesafioLinha> desafios(){return jdbc.query(sqlDesafios()+" order by d.DES_INICIO desc,d.DES_ID",desafioMapper());}
 public Optional<AulasDesafiosDados.DesafioLinha> desafio(long id){return jdbc.query(sqlDesafios()+" where d.DES_ID=?",desafioMapper(),id).stream().findFirst();}
 public List<AulasDesafiosDados.AvaliacaoLinha> avaliacoes(long id){return jdbc.query("select a.DAF_ID,a.DES_ID,a.ALU_ID,u.ALU_NOME,a.PRF_ID,p.PRF_NOME,a.DAF_TIPO,a.DAF_PESO,a.DAF_CINTURA,a.DAF_GORDURA,a.DAF_REGISTRO from DAF_AVALIACAO_DESAFIO a join ALU_ALUNO u on u.ALU_ID=a.ALU_ID join PRF_PROFISSIONAL p on p.PRF_ID=a.PRF_ID where a.DES_ID=? order by a.DAF_REGISTRO",(r,n)->{OffsetDateTime registro=r.getObject(11,OffsetDateTime.class);return new AulasDesafiosDados.AvaliacaoLinha(r.getLong(1),r.getLong(2),r.getLong(3),r.getString(4),r.getLong(5),r.getString(6),r.getString(7),r.getBigDecimal(8),r.getBigDecimal(9),r.getBigDecimal(10),registro,registro.isBefore(OffsetDateTime.now().minusHours(48)));},id);}
 public List<AulasDesafiosDados.EvolucaoLinha> evolucao(long desafio,String usuario){String q="select u.ALU_ID,u.ALU_NOME,i.DIN_INDICADOR,i.DIN_META,ini.DAF_PESO,ult.DAF_PESO,ini.DAF_CINTURA,ult.DAF_CINTURA,ini.DAF_GORDURA,ult.DAF_GORDURA from DIN_INSCRICAO_DESAFIO i join ALU_ALUNO u on u.ALU_ID=i.ALU_ID left join DAF_AVALIACAO_DESAFIO ini on ini.DAF_ID=i.DIN_AVALIACAO_INICIAL left join DAF_AVALIACAO_DESAFIO ult on ult.DAF_ID=(select max(x.DAF_ID) from DAF_AVALIACAO_DESAFIO x where x.DES_ID=i.DES_ID and x.ALU_ID=i.ALU_ID) where i.DES_ID=? and (?='' or u.ALU_USUARIO=?) order by u.ALU_NOME";return jdbc.query(q,(r,n)->new AulasDesafiosDados.EvolucaoLinha(r.getLong(1),r.getString(2),r.getString(3),r.getBigDecimal(4),r.getBigDecimal(5),r.getBigDecimal(6),r.getBigDecimal(7),r.getBigDecimal(8),r.getBigDecimal(9),r.getBigDecimal(10)),desafio,usuario,usuario);}
 private String sqlDesafios(){return "select d.DES_ID,d.DES_TITULO,d.DES_INDICADOR,d.DES_INICIO,d.DES_FIM,d.DES_STATUS,(select count(*) from DIN_INSCRICAO_DESAFIO i where i.DES_ID=d.DES_ID) from DES_DESAFIO d";}
 private org.springframework.jdbc.core.RowMapper<AulasDesafiosDados.DesafioLinha> desafioMapper(){return (r,n)->new AulasDesafiosDados.DesafioLinha(r.getLong(1),r.getString(2),r.getString(3),r.getDate(4).toLocalDate(),r.getDate(5).toLocalDate(),r.getString(6),r.getInt(7));}
}
